<script>
  import {onMount} from 'svelte';
  import {encryptBallot,verifyBoard} from './ballot.js';
  let page=$state(location.pathname==='/lab.html'?'ballot':'home'),step=$state('choose'),choice=$state(''),receipt=$state(null),busy=$state(false),error=$state('');
  let pendingBallot=null;
  let config=$state(null),configured=$state(false),lookup=$state(''),lookupResult=$state(''),auditResult=$state(''),totals=$state(null),savedCheckpoint=$state(null);
  let options=$derived(config?.election?.options??[]);
  onMount(async()=>{try{config=await api('/api/config');configured=config.mode==='encrypted-lab';try{savedCheckpoint=JSON.parse(localStorage.getItem('vote-anyway-checkpoint')||'null');}catch{}}catch{configured=false;}});
  async function api(url,init){const response=await fetch(url,init);const body=await response.json();if(!response.ok)throw Object.assign(Error(body.error||'Service unavailable. Please try again.'),{status:response.status});return body;}
  function navigate(next){page=next;error='';window.scrollTo({top:0,behavior:'smooth'});}
  function saveCheckpoint(value){savedCheckpoint=value;try{localStorage.setItem('vote-anyway-checkpoint',JSON.stringify(value));}catch{}}
  async function cast(){
    busy=true;error='';
    try{
      if(!pendingBallot||pendingBallot.choice!==choice)pendingBallot={choice,...await encryptBallot(config,choice)};
      const encrypted=pendingBallot;
      let record;
      try{record=await api('/api/vote',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ciphertext:encrypted.ciphertext})});}
      catch(e){
        if(e.status!==409)throw e;
        const found=await api('/api/receipt?receipt='+encrypted.receipt);
        if(!found.found)throw e;
        const board=await api('/api/board');const row=board.records.find(r=>r.receipt===encrypted.receipt);
        if(!row)throw e;
        record={receipt:encrypted.receipt,index:row.index,head:row.hash,checkpoint:{electionId:config.election.id,count:row.index,head:row.hash,signingPublicKey:config.signingPublicKey}};
      }
      if(record.receipt!==encrypted.receipt)throw Error('The returned receipt does not match the encrypted ballot.');
      receipt=record;step='receipt';
      // Verify continuity before replacing the previously observed checkpoint.
      const board=await api('/api/board');
      const check=await verifyBoard(board,config.signingPublicKey,config.election.id,savedCheckpoint,record.receipt);
      saveCheckpoint(check);
    }catch(e){error=(e.message||'Could not confirm the ballot.')+(step==='receipt'?' Your submission was recorded, but verification did not complete. Keep your receipt.':' If the connection failed, retrying this submission uses the same encrypted ballot.');}finally{busy=false;}
  }
  async function verify(){
    lookupResult='';error='';busy=true;
    try{
      const hash=lookup.trim().toLowerCase();
      if(!/^[a-f0-9]{64}$/.test(hash))throw Error('Enter the full 64-character receipt code.');
      const found=await api('/api/receipt?receipt='+hash);
      if(found.found){const board=await api('/api/board');const prior=!!savedCheckpoint;const check=await verifyBoard(board,config.signingPublicKey,config.election.id,savedCheckpoint,hash);saveCheckpoint(check);lookupResult='Included at record '+found.index+'. Signatures and record chain checked in your browser.'+(prior?' Consistent with your saved checkpoint.':' First observation: save a checkpoint to compare future records.');}
      else{const legacy=await api('/api/receipts/'+hash);lookupResult='Found in the earlier practice receipt register ('+new Date(legacy.createdAt).toLocaleDateString()+'). This fingerprint is not an encrypted ballot.';}
    }catch(e){error=e.message;}finally{busy=false;}
  }
  function download(value,name){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
  async function audit(){busy=true;error='';auditResult='';try{const board=await api('/api/board');const prior=!!savedCheckpoint;const check=await verifyBoard(board,config.signingPublicKey,config.election.id,savedCheckpoint);saveCheckpoint(check);auditResult=check.count+' signed records checked in your browser.'+(prior?' Consistent with your saved checkpoint.':' First observation: checkpoint saved in this browser.');totals=await api('/api/results');}catch(e){error=e.message;}finally{busy=false;}}
</script>

<svelte:head><title>Vote Anyway — {page==='home'?'Democracy, more often.':page==='ballot'?'Practice ballot':page==='verify'?'Check a receipt':page==='board'?'Public record':'The experiment'}</title></svelte:head>
<div class="notice">AN OPEN EXPERIMENT IN DEMOCRACY <span>Independent. Unofficial. In progress.</span></div>
<header>
  <button class="brand" onclick={()=>navigate('home')} aria-label="Vote Anyway home"><span class="mark">v<span>↗</span></span>vote anyway<span class="brand-dot">.</span></button>
  <nav aria-label="Main navigation"><a href="/devlog.html">Devlog</a><a href="/essay.html">Read the essay</a><button class:active={page==='about'} onclick={()=>navigate('about')}>The experiment</button><button class:active={page==='verify'} onclick={()=>navigate('verify')}>Check a receipt</button><button onclick={()=>{navigate('board');audit();}}>Public record</button><a href="https://github.com/anselm/vote-anyway" target="_blank" rel="noreferrer">GitHub ↗</a></nav>
</header>
<main>
{#if page==='home'}
  <section class="hero">
    <div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> A WORKING IDEA, OPEN TO EVERYONE</div><h1>Democracy,<br/>more <em>often.</em></h1><p class="intro">What if having a say were as simple as sending a message?</p><p class="muted hero-description">Vote Anyway is an experiment in making collective decisions more accessible, more frequent, and open to inspection. An essay and a working prototype, growing together.</p><div class="actions"><button class="primary" onclick={()=>{step='choose';choice='';pendingBallot=null;navigate('ballot');}}>Try a practice ballot <span>↗</span></button><button class="text-link" onclick={()=>navigate('about')}>Explore the idea ↓</button></div><p class="fine">No account needed. About a minute. Entirely unofficial.</p></div>
    <div class="hero-art" aria-hidden="true"><div class="art-grid"></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="ballot-paper"><span class="paper-kicker">YOUR VOICE</span><div class="paper-rule"></div><div class="paper-choice"><span>✓</span><i></i></div><div class="paper-choice"><span></span><i></i></div><div class="paper-choice"><span></span><i></i></div><div class="paper-bottom">A PART IN THE WHOLE. <b>↗</b></div></div><div class="art-label"><span class="live-dot"></span> MANY VOICES. SHARED POSSIBILITIES.</div><div class="art-corner">01 / AN EXPERIMENT</div></div>
  </section>
  <section class="principles"><article><span class="number">01</span><h2>A say, more often.</h2><p>Explore what changes when participation fits into everyday life.</p></article><article><span class="number">02</span><h2>Trust you can inspect.</h2><p>Build toward decisions whose records can be checked independently.</p></article><article><span class="number">03</span><h2>Ideas put into practice.</h2><p>Let working experiments inform the argument—and the next experiment.</p></article></section>
  <section class="lower"><div><div class="eyebrow">THE FIRST STEP</div><h2>Start small.<br/>Ask bigger questions.</h2></div><div><p>Try a fictional neighborhood ballot, check its receipt, and inspect the public record. The essay and its appendices explore the larger possibilities.</p><p class="muted">Explore browser-encrypted ballots, signed public records, and receipt verification. Identity, eligibility, and verifiable tallying remain research questions.</p><button class="text-link" onclick={()=>navigate('about')}>See what’s built and what’s next ↗</button></div></section>
{:else if page==='ballot'}
  <section class="workspace"><button class="back" onclick={()=>navigate('home')}>← Back to the experiment</button><div class="eyebrow">PRACTICE ELECTION / 001</div><h1 class="page-title">A little more<br/><em>collective possibility.</em></h1><p class="intro">{config?.election?.description??'Fictional neighborhood improvement exercise'}</p><p class="muted">EXPERIMENTAL VOTE — NOT AN OFFICIAL ELECTION. Participating here does not cast or change your real ballot.</p>
  <div class="step-line"><span class:current={step==='choose'}>01 Choose</span><span class:current={step==='review'}>02 Review</span><span class:current={step==='receipt'}>03 Receipt</span></div>
  {#if step==='choose'}<fieldset><legend>Choose one option</legend>{#each options as option}<label class="option" class:selected={choice===option.id}><input type="radio" name="choice" value={option.id} bind:group={choice}/><div><strong>{option.label}</strong></div></label>{/each}</fieldset><button class="primary" disabled={!choice||!configured} onclick={()=>step='review'}>Review my choice <span>→</span></button>
  {:else if step==='review'}<div class="panel"><div class="eyebrow">YOUR PRACTICE CHOICE</div><h2>{options.find(o=>o.id===choice)?.label}</h2><p>Your browser encrypts this fictional ballot before sending it. The server checks the selection, stores the ciphertext, and adds a signed record to the public log.</p><p class="fine">The operator can decrypt ballots and computes the demonstration totals. Repeat participation is allowed. This experiment does not establish voter eligibility or independently prove the tally.</p></div><div class="actions"><button class="primary" disabled={busy||!configured} onclick={cast}>{busy?'Encrypting and submitting…':'Submit experimental ballot'} <span>↗</span></button><button class="text-link" disabled={busy} onclick={()=>step='choose'}>Change choice</button></div>
  {:else}<div class="panel receipt"><span class="success-icon">✓</span><div class="eyebrow">PRACTICE COMPLETE</div><h2>Your voice starts somewhere.</h2><p>Your encrypted ballot is recorded in the public log at position {receipt.index}.</p><label for="receipt-code">Your receipt code</label><code id="receipt-code">{receipt.receipt}</code><p class="fine">EXPERIMENTAL VOTE — NOT AN OFFICIAL ELECTION. Participating here does not cast or change your real ballot. Keep your receipt and checkpoint to check the record later.</p><div class="actions"><button class="primary" onclick={()=>{lookup=receipt.receipt;lookupResult='';navigate('verify');}}>Check this receipt →</button><button class="text-link" onclick={()=>download(receipt,'vote-anyway-receipt.json')}>Download receipt ↓</button></div></div>{/if}
  {#if error}<p class="error" role="alert">{error}</p>{/if}<p class="storage-note">{configured?'Encrypted-ballot experiment connected.':'The voting experiment is unavailable. Please try again shortly.'}</p></section>
{:else if page==='verify'}
  <section class="workspace"><button class="back" onclick={()=>navigate('home')}>← Home</button><div class="eyebrow">FOLLOW THE RECORD</div><h1 class="page-title">A receipt.<br/><em>A place to begin.</em></h1><p class="intro">Check a practice receipt.</p><p class="muted">Paste your receipt code. Your browser checks the signed public log and compares it with any checkpoint saved on this device.</p><form class="panel" onsubmit={(event)=>{event.preventDefault();verify();}}><label for="lookup">Receipt code</label><input id="lookup" class="code-input" bind:value={lookup} placeholder="Enter your 64-character receipt code" autocomplete="off" spellcheck="false" required/><button class="primary" disabled={busy}>{busy?'Checking…':'Find my receipt'} <span>→</span></button>{#if lookupResult}<p class="result" role="status">✓ {lookupResult}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}</form><p class="fine">This checks signed record integrity and inclusion. It does not verify voter eligibility, ballot intent, or the server’s tally. The signing key is obtained from this site; independent checking requires an authentic key and a trusted earlier checkpoint.</p></section>
{:else if page==='board'}
  <section class="workspace"><button class="back" onclick={()=>navigate('home')}>← Home</button><div class="eyebrow">OPEN TO INSPECTION</div><h1 class="page-title">The public<br/><em>record.</em></h1><p class="intro">Signed records, open questions.</p><p>Check the encrypted records in your browser, download them, or use the independent checker. A saved checkpoint lets you detect a shorter or conflicting history later.</p><div class="actions"><button class="primary" disabled={busy||!configured} onclick={audit}>{busy?'Checking…':'Verify public record'}</button><a class="text-link" href="/api/board" download="board.json">Download log ↓</a><a class="text-link" href="/api/signing-key.pem" download="signing-public-key.pem">Public key ↓</a></div>
  {#if auditResult}<p class="result" role="status">{auditResult}</p>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if savedCheckpoint}<button class="text-link" onclick={()=>download(savedCheckpoint,'checkpoint.json')}>Save checkpoint ↓</button>{/if}
  {#if totals}<div class="panel"><h2>Demonstration totals</h2>{#each options as option}<p>{option.label}: <strong>{totals.counts[option.id]}</strong></p>{/each}<p>{totals.total} submissions. {totals.warning}</p></div>{/if}
  <h2>Check independently</h2><p>Download <a href="/verify-log.mjs" download>the checker</a> and its <a href="/verify-board.mjs" download>verification module</a> into the same folder as the log and public key. Run with Node 22 or later:</p><pre class="verifier-command">node verify-log.mjs board.json signing-public-key.pem</pre><p>Add a receipt code (or <code>-</code>) and an earlier checkpoint filename to check inclusion and continuity.</p><p class="fine">Trust depends on an authentic public key and independently retained checkpoints. Signatures cannot stop the operator from showing different histories to different people. The operator can decrypt ballots; the tally is not independently proven. These are fictional volunteer submissions, not an official election.</p></section>
{:else}
  <section class="workspace about"><button class="back" onclick={()=>navigate('home')}>← Home</button><div class="eyebrow">THEORY ↔ ACTION</div><h1 class="page-title">An argument.<br/><em>And an experiment.</em></h1><p class="intro">What becomes possible when collective decisions are easier to make?</p><p>Voting sits within a wider system: sensing what is happening, deliberating about what matters, deciding together, acting, and learning from the result. A better ballot is one part of that picture.</p><p>Vote Anyway brings an essay and a software experiment into the same place. The essay explores secure internet voting and its democratic possibilities. The prototype gives us something concrete to question, inspect, and improve.</p><div class="roadmap"><div class="eyebrow">WHERE WE ARE</div><article><span class="status">NOW</span><div><h2>A working beginning</h2><p>A fictional ballot with browser encryption, a review step, signed public records, downloadable receipts, and an independent record checker. PostgreSQL stores the encrypted records across server restarts.</p></div></article><article><span class="status next">NEXT</span><div><h2>Identity, eligibility, verification</h2><p>Connect attest.monster, define election participation policies, and select a reviewed cryptographic protocol. Keep identity, eligibility decisions, encrypted ballots, and public audit records separate.</p></div></article><article><span class="status next">EXPLORE</span><div><h2>More ways to decide</h2><p>Provisional ballots and eligibility adjudication. Social trust graphs inspired by Advogato. Ranked and approval voting. Later, delegation and liquid democracy.</p></div></article></div><h2>The companion essay: Vote Anyway</h2><p>The core essay makes the persuasive argument. Linked appendices carry the technical detail, citations, previous work, and implementation questions. The development log also holds the evolving outline, earlier drafts, and research notes.</p><a class="primary inline" href="https://github.com/anselm/vote-anyway" target="_blank" rel="noreferrer">Follow the work on GitHub ↗</a> <a class="primary inline" href="/essay.html">Read the essay ↗</a></section>
{/if}
</main>
<footer><button class="brand small" onclick={()=>navigate('home')}>vote anyway.</button><p>An open experiment. A work in progress.</p><span>BUILT IN PUBLIC ↗</span></footer>
